-- ============================================================================
-- seed_kenya_questions_batch6.sql
-- 73 more questions, mostly hard and medium, aimed at the thinnest categories
-- (Swahili & Sheng, Kenyan Food & Culture, Safaricom & Tech, Matatus & Transport,
-- Music & Entertainment) plus extra hard questions in History, Geography, Sports
-- and Wildlife. Each has a "Did you know?" line.
-- Run AFTER 024_content_quality.sql. Safe to re-run (skips existing question text).
-- IMPORTANT: have a Kenyan reviewer check every fact (see batch6_review.md) before release.
-- ============================================================================

insert into public.categories (name)
select c.name from (values ($q$General Knowledge$q$), ($q$Kenyan Food & Culture$q$), ($q$Kenyan Geography$q$), ($q$Kenyan History$q$), ($q$Kenyan Sports$q$), ($q$Kenyan Wildlife & Culture$q$), ($q$Matatus & Transport$q$), ($q$Music & Entertainment$q$), ($q$Safaricom & Tech$q$), ($q$Swahili & Sheng$q$)) as c(name)
where not exists (select 1 from public.categories x where x.name = c.name);

insert into public.questions
  (category_id, question_text, option_a, option_b, option_c, option_d, correct_option, difficulty, did_you_know)
select (select id from public.categories where name = v.cat limit 1),
       v.question_text, v.a, v.b, v.c, v.d, v.correct, v.difficulty, v.fact
from (values
  ($q$Swahili & Sheng$q$, $q$What is the Swahili word for "window"?$q$, $q$Dirisha$q$, $q$Mlango$q$, $q$Paa$q$, $q$Ukuta$q$, 'a', 'hard', $q$"Mlango" is a door, "paa" is a roof and "ukuta" is a wall.$q$),
  ($q$Swahili & Sheng$q$, $q$What is the Swahili word for "kitchen"?$q$, $q$Choo$q$, $q$Jiko$q$, $q$Chumba$q$, $q$Bustani$q$, 'b', 'hard', $q$"Jiko" can also mean a stove or cooker.$q$),
