  ($q$Swahili & Sheng$q$, $q$In Sheng, who is your "buda"?$q$, $q$Your brother$q$, $q$Your teacher$q$, $q$Your father$q$, $q$Your neighbour$q$, 'c', 'medium', $q$"Mathe" is the Sheng word for mother.$q$),
  ($q$Swahili & Sheng$q$, $q$In Sheng, what is "chapaa"?$q$, $q$Food$q$, $q$A house$q$, $q$A car$q$, $q$Money$q$, 'd', 'medium', $q$"Pesa" is the Swahili word. "Chapaa" and "ganji" are Sheng words for money.$q$),
  ($q$Swahili & Sheng$q$, $q$In Sheng, where are you if you are at "kejani"?$q$, $q$At home$q$, $q$At school$q$, $q$At church$q$, $q$At the market$q$, 'a', 'medium', $q$It comes from "keja", Sheng for a house.$q$),
  ($q$Swahili & Sheng$q$, $q$What number is "sabini" in Swahili?$q$, $q$17$q$, $q$7$q$, $q$70$q$, $q$700$q$, 'c', 'medium', $q$"Saba" is 7 and "sabini" is 70.$q$),
  ($q$Swahili & Sheng$q$, $q$Swahili belongs to which language family?$q$, $q$Nilotic$q$, $q$Cushitic$q$, $q$Semitic$q$, $q$Bantu$q$, 'd', 'hard', $q$Swahili is a Bantu language with many words borrowed from Arabic.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Matoke is made mainly from which ingredient?$q$, $q$Green bananas$q$, $q$Sweet potatoes$q$, $q$Cassava$q$, $q$Millet$q$, 'a', 'medium', $q$Matoke is steamed or boiled until soft and often served with stew.$q$),
  ($q$Kenyan Food & Culture$q$, $q$Bhajia, a popular street snack, is made from potato slices in what kind of batter?$q$, $q$Maize flour$q$, $q$Chickpea flour$q$, $q$Rice flour$q$, $q$Wheat flour$q$, 'b', 'medium', $q$Bhajia came to Kenya with Indian communities and is often eaten with kachumbari.$q$),
  ($q$Kenyan Food & Culture$q$, $q$What is mutura, a popular Kenyan street food?$q$, $q$A fried dough ball$q$, $q$A fish stew$q$, $q$A maize porridge$q$, $q$A traditional sausage$q$, 'd', 'medium', $q$Mutura is often roasted over charcoal and sold on street corners.$q$),
  ($q$Kenyan Food & Culture$q$, $q$What does "maziwa lala" literally mean in Swahili?$q$, $q$Sleeping milk$q$, $q$Sweet milk$q$, $q$Morning milk$q$, $q$Cold milk$q$, 'a', 'hard', $q$It is fermented milk, a bit like yoghurt.$q$),
